// Paramètres de la baseline (prompts/baseline_v1.md), à modifier ici. Un seul appel de chat (2 avec la relance).
// Pour comparer, lister les mêmes sections que l'exécution de 10-argumentaire comparée (identifiants de prompts/sections.json).
// Pas d'exécution sans l'accord du groupe (quota : 20 appels de chat par jour).
return [{ json: {
  modele: 'gemini-3.8-flash',
  sections: ['contexte', 'enjeux_fda', 'technique', 'ethique', 'social_economique', 'reglementaire', 'parcours_soins', 'autres', 'conclusion'],
} }];

// Remplit le prompt versionné (prompts/baseline_v1.md) : même consigne et même structure que le pipeline, position POUR,
// sans corpus ni garde-fous. Un seul appel pour tout l'argumentaire ; le modèle doit citer ses sources.
const { modele, sections: demandees } = $('Paramètres').first().json;
const fichiers = {};
$input.all().forEach(({ json }, i) => {
  fichiers[$('Lire les fichiers').itemMatching(i).binary.data.fileName] = json.data;
});
const config = JSON.parse(fichiers['sections.json']);
const inconnues = demandees.filter((id) => !config.sections.some((s) => s.id === id));
if (inconnues.length) throw new Error(`Paramètres : section(s) inconnue(s) : ${inconnues.join(', ')}`);
const sections = config.sections.filter((s) => demandees.includes(s.id)).map(({ id, titre, consigne }) => ({ id, titre, consigne }));
const valeurs = { POSITION: 'POUR', SECTIONS: sections.map((s) => `- ${s.id} : ${s.titre}. ${s.consigne}`).join('\n') };
const prompt = fichiers['baseline_v1.md'].replace(/\{\{(\w+)\}\}/g, (m, k) => valeurs[k] ?? m);
// Schéma imposé à Gemini (mode JSON), au même titre que pour le rédacteur du pipeline.
const chaine = { type: 'STRING' };
const schema = {
  type: 'OBJECT',
  properties: {
    sections: { type: 'ARRAY', items: { type: 'OBJECT', properties: {
      id: chaine,
      paragraphes: { type: 'ARRAY', items: { type: 'OBJECT', properties: {
        texte: chaine, references: { type: 'ARRAY', items: { type: 'INTEGER' } },
      }, required: ['texte', 'references'] } },
    }, required: ['id', 'paragraphes'] } },
    references: { type: 'ARRAY', items: { type: 'OBJECT', properties: {
      numero: { type: 'INTEGER' }, reference: chaine,
    }, required: ['numero', 'reference'] } },
  },
  required: ['sections', 'references'],
};
return [{ json: { run_id: $now.toFormat('yyyyLLdd-HHmmss'), debut: Date.now(), modele, sections, prompt, schema } }];

// Assemblage de la baseline : Markdown (références générées par le modèle, non vérifiées), JSON brut pour eval/evaluer.py
// et une ligne dans runs.jsonl. Aucun garde-fou : c'est le point de comparaison du pipeline.
const prep = $('Prompt de la baseline').first().json;
const r = $json;
const tentatives = $prevNode.name === 'Baseline (2e tentative)' ? 2 : 1;
let sortie = null;
let erreur = null;
if (r.statusCode !== 200) {
  const motif = r.statusCode ? `HTTP ${r.statusCode} : ${r.body?.error?.message ?? ''}` : (r.error?.message ?? 'pas de réponse');
  erreur = `appel Gemini en échec après ${tentatives} tentative(s) (${motif})`;
} else {
  const texte = (r.body?.candidates?.[0]?.content?.parts ?? []).filter((p) => !p.thought).map((p) => p.text).join('');
  try { sortie = JSON.parse(texte); } catch { erreur = "la réponse n'est pas du JSON valide"; }
}
const recues = new Map((sortie?.sections ?? []).map((s) => [s.id, s]));
const lignes = [
  "# Baseline : autorisation FDA de la notification d'hypertension de l'Apple Watch",
  '',
  `Position : **POUR** · exécution \`${prep.run_id}\` · modèle \`${prep.modele}\` · prompt \`baseline_v1\` · **Gemini seul, sans RAG ni garde-fous**`,
  '',
  "> Les références ci-dessous ont été générées par le modèle et **n'ont pas été vérifiées**.",
  '',
];
if (erreur) lignes.push(`> Échec : ${erreur}`, '');
for (const s of prep.sections) {
  lignes.push(`## ${s.titre}`, '');
  const recue = recues.get(s.id);
  if (!recue?.paragraphes?.length) { lignes.push('> Section absente de la réponse.', ''); continue; }
  for (const p of recue.paragraphes) lignes.push(`${p.texte}${p.references?.length ? ` [${p.references.join(', ')}]` : ''}`, '');
}
lignes.push('## Références (générées par le modèle, non vérifiées)', '');
for (const ref of sortie?.references ?? []) lignes.push(`${ref.numero}. ${ref.reference}`);
const resume = {
  sections_presentes: prep.sections.filter((s) => recues.get(s.id)?.paragraphes?.length).length,
  sections_inattendues: [...recues.keys()].filter((id) => !prep.sections.some((s) => s.id === id)),
  paragraphes: prep.sections.reduce((n, s) => n + (recues.get(s.id)?.paragraphes?.length ?? 0), 0),
  references: sortie?.references?.length ?? 0,
  erreur,
};
const brut = {
  run_id: prep.run_id, modele: prep.modele, prompt: 'baseline_v1.md', sections_demandees: prep.sections.map((s) => s.id),
  tentatives, erreur, version: r.body?.modelVersion, usage: r.body?.usageMetadata, sortie,
};
const run = {
  run_id: prep.run_id, horodatage: $now.toISO(), workflow: '50-baseline', modele: prep.modele, version_modele: r.body?.modelVersion,
  prompts: ['baseline_v1.md', 'sections.json v1'], sections: prep.sections.map((s) => s.id),
  appels: { chat: tentatives, embeddings: 0 }, tentatives: { baseline: tentatives }, tokens: [r.body?.usageMetadata],
  duree_s: Math.round((Date.now() - prep.debut) / 1000), ...resume,
};
const fichier = (nom, contenu, mimeType, ajout = false) => ({
  json: { nom, ajout },
  binary: { data: { data: Buffer.from(contenu, 'utf8').toString('base64'), mimeType, fileName: nom } },
});
return [
  fichier(`baseline_${prep.run_id}.md`, lignes.join('\n') + '\n', 'text/markdown'),
  fichier(`baseline_${prep.run_id}.json`, JSON.stringify(brut, null, 2) + '\n', 'application/json'),
  fichier('runs.jsonl', JSON.stringify(run) + '\n', 'application/x-ndjson', true),
];
